function snapshotMirrorSummary(mirror) {
  if (!mirror || !mirror.status)
    return null;
  switch (mirror.status) {
    case "written":
    case "exists":
      return {
        tone: "ok",
        text: mirror.uri ? `Off-Cyntro restore copy: ${mirror.uri}` : "Off-Cyntro restore copy written"
      };
    case "failed":
      return {
        tone: "warn",
        text: `Off-Cyntro restore copy not written${mirror.error ? ` — ${mirror.error}` : ""} (primary snapshot still guards rollback)`
      };
    case "disabled":
      return { tone: "muted", text: "Customer-account mirror not configured" };
    default:
      return { tone: "muted", text: `Customer-account mirror: ${mirror.status}` };
  }
}
async function operationalRequest(systemName, path, init) {
  const response = await fetch(`/api/proxy/operational-map/${encodeURIComponent(systemName)}/${path}`, { cache: "no-store", ...init });
  const body = await response.json().catch(() => null);
  if (!response.ok) {
    const detail = body?.detail ?? body?.error;
    const message = typeof detail === "string" ? detail : detail ? JSON.stringify(detail) : `Operational API returned ${response.status}`;
    throw new Error(message);
  }
  return body;
}

